// UIInputView owns the native keyboard material. Do not paint a settings
// list color over it or add a second bottom safe-area inset to its height.
self.allowsSelfSizing = true

required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }

private func updateSurface() {
    let dark = self.traitCollection.userInterfaceStyle == .dark
    self.backgroundColor = dark
        ? UIColor(red: 0.12, green: 0.13, blue: 0.14, alpha: 1)
        : UIColor(red: 0.82, green: 0.83, blue: 0.85, alpha: 1)
    self.layer.borderColor = UIColor(white: dark ? 1 : 0, alpha: dark ? 0.20 : 0.16).cgColor
    self.layer.borderWidth = 1 / max(1, self.traitCollection.displayScale)
}

override func traitCollectionDidChange(_ previousTraitCollection: UITraitCollection?) {
    super.traitCollectionDidChange(previousTraitCollection)
    self.updateSurface()
    self.setNeedsLayout()
}

override var intrinsicContentSize:

super.layoutSubviews()
self.updateSurface()
let inset: CGFloat = 8
let left = inset + self.safeAreaInsets.left
let right = inset + self.safeAreaInsets.right
let contentWidth = max(0, self.bounds.width - left - right)
let headingLeft = max(left, self.layer.cornerRadius + inset)
let headingRight = max(right, self.layer.cornerRadius + inset)
let headingWidth = max(0, self.bounds.width - headingLeft - headingRight)
let headingSize = self.heading.sizeThatFits(CGSize(width: headingWidth, height: CGFloat.greatestFiniteMagnitude))
let headingHeight = max(36, ceil(headingSize.height) + 8)
self.heading.frame = CGRect(x: headingLeft, y: 4, width: headingWidth, height: headingHeight)

    panel.clipsToBounds = true
}

override func layout() {
    super.layout()
    // The parent may reduce the visible input bounds after updateLayout,
    // for example while dragging below a tall editing field. Keep the
    // surface and its controls inside those actual bounds, not a stale
    // preferred keyboard size or UIKit's intermediate autoresizing result.
    if self.panel.frame != self.bounds {
        self.panel.frame = self.bounds
        self.panel.setNeedsLayout()
    }
}

